package memory

import (
	"context"
	"sync"
)

// globalMemoryStore holds the global memory store instance for API access.
// Set by the ExtProc router during initialization.
var (
	globalMemoryStore Store
	globalStoreMu     sync.RWMutex
)

// SetGlobalMemoryStore sets the global memory store instance.
// Called by the ExtProc router after creating the memory store.
func SetGlobalMemoryStore(store Store) {
	globalStoreMu.Lock()
	defer globalStoreMu.Unlock()
	globalMemoryStore = store
}

// GetGlobalMemoryStore returns the global memory store instance.
// Returns nil if memory is not enabled or not yet initialized.
func GetGlobalMemoryStore() Store {
	globalStoreMu.RLock()
	defer globalStoreMu.RUnlock()
	return globalMemoryStore
}

// Store defines the interface for storing and retrieving memories.
// Implementations must be thread-safe.
type Store interface {
	// Store saves a new memory.
	// Returns error if the memory ID already exists.
	Store(ctx context.Context, memory *Memory) error

	// Retrieve performs semantic search for relevant memories.
	// Uses embedding-based similarity search.
	Retrieve(ctx context.Context, opts RetrieveOptions) ([]*RetrieveResult, error)

	// Get retrieves a memory by ID.
	// Returns nil and error if the memory doesn't exist.
	Get(ctx context.Context, id string) (*Memory, error)

	// Update modifies an existing memory.
	// Returns error if the memory doesn't exist.
	Update(ctx context.Context, id string, memory *Memory) error

	// List returns memories matching the filter criteria with pagination.
	// UserID is required. Returns memories sorted by created_at descending.
	List(ctx context.Context, opts ListOptions) (*ListResult, error)

	// Forget deletes a memory by ID.
	// Returns error if the memory doesn't exist.
	Forget(ctx context.Context, id string) error

	// ForgetByScope deletes all memories matching the scope.
	// Scope includes UserID (required), ProjectID (optional), Types (optional).
	ForgetByScope(ctx context.Context, scope MemoryScope) error

	// IsEnabled returns whether the store is enabled.
	IsEnabled() bool

	// CheckConnection verifies the store connection is healthy.
	CheckConnection(ctx context.Context) error

	// Close releases resources held by the store.
	Close() error
}

package memory

import (
	"time"

	"github.com/vllm-project/semantic-router/src/semantic-router/pkg/config"
)

// MemoryType represents the category of a memory in the agentic memory system.
type MemoryType string

const (
	// MemoryTypeSemantic represents facts, preferences, knowledge.
	// Example: "User's budget for Hawaii is $10,000"
	MemoryTypeSemantic MemoryType = "semantic"

	// MemoryTypeProcedural represents instructions, how-to, steps.
	// Example: "To deploy payment-service: run npm build, then docker push"
	MemoryTypeProcedural MemoryType = "procedural"

	// MemoryTypeEpisodic represents session summaries, past events.
	// Example: "On Dec 29 2024, user planned Hawaii vacation with $10K budget"
	MemoryTypeEpisodic MemoryType = "episodic"
)

// Memory represents a stored memory unit in the agentic memory system
type Memory struct {
	// ID is the unique identifier for this memory
	ID string `json:"id"`

	// Type is the category of this memory (semantic, procedural, episodic)
	Type MemoryType `json:"type"`

	// Content is the actual memory text
	// Should be self-contained with context (e.g., "budget for Hawaii is $10K" not just "$10K")
	Content string `json:"content"`

	// Embedding is the vector representation (not serialized to JSON)
	Embedding []float32 `json:"-"`

	// UserID is the owner of this memory (for user isolation)
	UserID string `json:"user_id"`

	// ProjectID is an optional project scope
	ProjectID string `json:"project_id,omitempty"`

	// Source indicates where this memory came from
	Source string `json:"source,omitempty"`

	// CreatedAt is when the memory was first stored
	CreatedAt time.Time `json:"created_at"`

	// UpdatedAt is when the memory was last modified
	UpdatedAt time.Time `json:"updated_at,omitempty"`

	// AccessCount tracks how often this memory is retrieved (used for retention score S = S0 + AccessCount)
	AccessCount int `json:"access_count"`

	// LastAccessed is when the memory was last retrieved (used for retention score t and reinforcement)
	LastAccessed time.Time `json:"last_accessed,omitempty"`

	// Importance is a score for prioritizing memories (0.0 to 1.0)
	Importance float32 `json:"importance"`

	// --- Provenance fields ---

	// CreatedByUserID is the user whose conversation produced this memory.
	CreatedByUserID string `json:"created_by_user_id,omitempty"`

	// ConversationID is the session that produced this memory.
	ConversationID string `json:"conversation_id,omitempty"`

	// CreatedVia records the creation method: "llm_extraction", "api", "import".
	CreatedVia string `json:"created_via,omitempty"`
}

// RetrieveResult represents a memory retrieved from search with its relevance score
type RetrieveResult struct {
	// Memory is the retrieved memory
	Memory *Memory `json:"memory"`

	// Score is the similarity score (0.0 to 1.0, higher = more relevant)
	Score float32 `json:"score"`
}

// RetrieveOptions configures memory retrieval
type RetrieveOptions struct {
	// Query is the search query (will be embedded for vector search)
	Query string

	// UserID filters memories to this user only
	UserID string

	// ProjectID optionally filters to a specific project
	ProjectID string

	// Types optionally filters to specific memory types
	Types []MemoryType

	// Limit is the maximum number of results to return (default: 5)
	Limit int

	// Threshold is the minimum similarity score (range 0.0 to 1.0, default: 0.70)
	Threshold float32

	// HybridSearch enables BM25 + n-gram re-ranking on top of vector search
	HybridSearch bool

	// HybridMode selects the score fusion method: "weighted" (default) or "rrf"
	HybridMode string

	// AdaptiveThreshold enables cluster-based adaptive thresholding.
	// When true, the retriever detects the largest score gap among candidates
	// and only returns those above the gap, subject to the base Threshold
	// as a floor. This avoids injecting weakly-relevant memories.
	AdaptiveThreshold bool
}

// DefaultMemoryConfig returns a default memory configuration.
// EmbeddingModel is intentionally omitted - let router auto-detect from embedding_models config.
func DefaultMemoryConfig() config.MemoryConfig {
	return config.MemoryConfig{
		Milvus: config.MemoryMilvusConfig{
			Dimension: 384, // Safe default, will be overridden by router
		},
		DefaultRetrievalLimit:      5,
		DefaultSimilarityThreshold: 0.70,
	}
}

// ListOptions configures memory listing (non-semantic, filter-based retrieval)
type ListOptions struct {
	// UserID filters memories to this user only (required)
	UserID string

	// Types optionally filters to specific memory types
	Types []MemoryType

	// Limit is the maximum number of results to return (default: 20, max: 100)
	Limit int
}

// ListResult contains the memories returned by a List operation
type ListResult struct {
	// Memories is the list of memories returned
	Memories []*Memory `json:"memories"`

	// Total is the total number of matching memories
	Total int `json:"total"`

	// Limit is the limit that was applied
	Limit int `json:"limit"`
}

// MemoryFilter is the interface for post-retrieval, pre-injection memory
// validation. Implementations score, trim, and filter retrieved memories
// before they are injected into the LLM request context.
//
// Returning nil or an empty slice signals that no memories should be injected.
// Implementations must be safe for concurrent use.
type MemoryFilter interface {
	Filter(memories []*RetrieveResult) []*RetrieveResult
}

// MemoryFilterFactory constructs a MemoryFilter from global and optional
// per-decision configuration. Returning nil means filtering is disabled
// (equivalent to NoopFilter).
type MemoryFilterFactory func(global config.MemoryReflectionConfig, perDecision *config.MemoryReflectionConfig) MemoryFilter

// MemoryScope defines the scope for bulk operations (e.g., ForgetByScope)
type MemoryScope struct {
	// UserID is required - all operations are user-scoped
	UserID string

	// ProjectID optionally narrows scope to a project
	ProjectID string

	// Types optionally narrows scope to specific memory types
	Types []MemoryType
}

package memory

import (
	"context"
	"fmt"
	"strings"
	"time"

	"github.com/milvus-io/milvus-sdk-go/v2/client"

	"github.com/vllm-project/semantic-router/src/semantic-router/pkg/config"
	"github.com/vllm-project/semantic-router/src/semantic-router/pkg/observability/logging"
)

// DefaultMaxRetries is the default number of retry attempts for transient errors
// DefaultRetryBaseDelay is the base delay for exponential backoff (in milliseconds)
const (
	DefaultMaxRetries     = 3
	DefaultRetryBaseDelay = 100
)

// MilvusStore provides memory retrieval from Milvus with similarity threshold filtering
type MilvusStore struct {
	client          client.Client
	collectionName  string
	config          config.MemoryConfig
	enabled         bool
	maxRetries      int
	retryBaseDelay  time.Duration
	embeddingConfig EmbeddingConfig // Unified embedding configuration
}

// MilvusStoreOptions contains configuration for creating a MilvusStore
//
//	Client is the Milvus client instance
//	CollectionName is the name of the Milvus collection
//	Config is the memory configuration
//	Enabled controls whether the store is active
//	EmbeddingConfig is the unified embedding configuration (optional, defaults to mmbert/768)
type MilvusStoreOptions struct {
	Client          client.Client
	CollectionName  string
	Config          config.MemoryConfig
	Enabled         bool
	EmbeddingConfig *EmbeddingConfig // Optional: if nil, derived from Config.Embedding
}

// NewMilvusStore creates a new MilvusStore instance

func NewMilvusStore(options MilvusStoreOptions) (*MilvusStore, error) {
	if !options.Enabled {
		logging.ComponentDebugEvent("memory", "milvus_store_init_skipped", map[string]interface{}{
			"reason":  "disabled",
			"enabled": false,
		})
		return &MilvusStore{
			enabled: false,
		}, nil
	}

	if options.Client == nil {
		return nil, fmt.Errorf("milvus client is required")
	}

	if options.CollectionName == "" {
		return nil, fmt.Errorf("collection name is required")
	}

	// Use default config if not provided
	cfg := options.Config
	if cfg.EmbeddingModel == "" {
		cfg = DefaultMemoryConfig()
	}

	// Initialize embedding configuration
	var embeddingCfg EmbeddingConfig
	if options.EmbeddingConfig != nil {
		embeddingCfg = *options.EmbeddingConfig
	} else {
		embeddingCfg = EmbeddingConfig{Model: EmbeddingModelBERT}
	}

	store := &MilvusStore{
		client:          options.Client,
		collectionName:  options.CollectionName,
		config:          cfg,
		enabled:         options.Enabled,
		maxRetries:      DefaultMaxRetries,
		retryBaseDelay:  DefaultRetryBaseDelay * time.Millisecond,
		embeddingConfig: embeddingCfg,
	}

	// Auto-create collection if it doesn't exist
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()
	if err := store.ensureCollection(ctx); err != nil {
		return nil, fmt.Errorf("failed to ensure collection exists: %w", err)
	}

	logging.ComponentEvent("memory", "milvus_store_initialized", map[string]interface{}{
		"collection_name": store.collectionName,
		"embedding_model": store.embeddingConfig.Model,
		"dimension":       store.config.Milvus.Dimension,
	})

	return store, nil
}

func (m *MilvusStore) IsEnabled() bool {
	return m.enabled
}

func (m *MilvusStore) CheckConnection(ctx context.Context) error {
	if !m.enabled {
		return nil
	}

	if m.client == nil {
		return fmt.Errorf("milvus client is not initialized")
	}

	// Check if collection exists
	hasCollection, err := m.client.HasCollection(ctx, m.collectionName)
	if err != nil {
		return fmt.Errorf("failed to check collection existence: %w", err)
	}

	if !hasCollection {
		return fmt.Errorf("collection '%s' does not exist", m.collectionName)
	}

	return nil
}

func (m *MilvusStore) Close() error {
	// Note: We don't close the client here as it might be shared
	// The caller is responsible for managing the client lifecycle
	return nil
}

func isTransientError(err error) bool {
	if err == nil {
		return false
	}

	errStr := strings.ToLower(err.Error())

	// Check for common transient error patterns
	transientPatterns := []string{
		"connection",
		"timeout",
		"deadline exceeded",
		"context deadline exceeded",
		"unavailable",
		"temporary",
		"retry",
		"rate limit",
		"too many requests",
		"server error",
		"internal error",
		"service unavailable",
		"network",
		"broken pipe",
		"connection reset",
		"no connection",
		"connection refused",
	}

	for _, pattern := range transientPatterns {
		if strings.Contains(errStr, pattern) {
			return true
		}
	}

	return false
}

func (m *MilvusStore) retryWithBackoff(ctx context.Context, operation func() error) error {
	var lastErr error

	for attempt := 0; attempt < m.maxRetries; attempt++ {
		lastErr = operation()

		// If no error or non-transient error, return immediately
		if lastErr == nil || !isTransientError(lastErr) {
			return lastErr
		}

		// If this is the last attempt, return the error
		if attempt == m.maxRetries-1 {
			logging.Warnf("MilvusStore: operation failed after %d retries: %v", m.maxRetries, lastErr)
			return lastErr
		}

		// Calculate exponential backoff delay
		// Cap the exponent to avoid overflow (max 30 for safety)
		exponent := attempt
		if exponent < 0 {
			exponent = 0
		} else if exponent > 30 {
			exponent = 30
		}
		delay := m.retryBaseDelay * time.Duration(1<<exponent) // 2^attempt * baseDelay

		logging.Debugf("MilvusStore: transient error on attempt %d/%d, retrying in %v: %v",
			attempt+1, m.maxRetries, delay, lastErr)

		// Wait with context cancellation support
		select {
		case <-ctx.Done():
			return fmt.Errorf("context cancelled during retry: %w", ctx.Err())
		case <-time.After(delay):
			// Continue to next retry
		}
	}

	return lastErr
}

