1	package memory
2	
3	import (
4		"context"
5		"encoding/json"
6		"fmt"
7		"time"
8	
9		"github.com/milvus-io/milvus-sdk-go/v2/client"
10		"github.com/milvus-io/milvus-sdk-go/v2/entity"
11	
12		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/observability/logging"
13		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/vectorstore"
14	)
15	
16	func (m *MilvusStore) Retrieve(ctx context.Context, opts RetrieveOptions) ([]*RetrieveResult, error) {
17		startTime := time.Now()
18		backend := "milvus"
19		operation := "retrieve"
20		status := "success"
21		resultCount := 0
22	
23		defer func() {
24			duration := time.Since(startTime).Seconds()
25			RecordMemoryRetrieval(backend, operation, status, opts.UserID, duration, resultCount)
26		}()
27	
28		limit, threshold, err := m.normalizeRetrieveOpts(opts)
29		if err != nil {
30			status = "error"
31			return nil, err
32		}
33	
34		logging.Debugf("MilvusStore.Retrieve: query=%s, user_id='%s', limit=%d, threshold=%.4f, hybrid=%v (mode=%s)",
35			logging.ContentDescriptor(opts.Query), opts.UserID, limit, threshold, opts.HybridSearch, opts.HybridMode)
36	
37		embedding, err := GenerateEmbedding(opts.Query, m.embeddingConfig)
38		if err != nil {
39			status = "error"
40			return nil, fmt.Errorf("failed to generate embedding: %w", err)
41		}
42	
43		searchResult, err := m.searchMemoryVectors(ctx, embedding, retrieveFilterExpr(opts.UserID, opts.Types), retrieveSearchTopK(limit, opts.HybridSearch))
44		if err != nil {
45			status = "error"
46			return nil, err
47		}
48	
49		if len(searchResult) == 0 || searchResult[0].ResultCount == 0 {
50			logging.Debugf("MilvusStore.Retrieve: no results found")
51			status = "miss"
52			return []*RetrieveResult{}, nil
53		}
54	
55		results := m.finalizeRetrieveResults(searchResult[0], opts, limit, threshold)
56		resultCount = len(results)
57		if resultCount > 0 {
58			status = "hit"
59		} else {
60			status = "miss"
61		}
62		return results, nil
63	}
64	
65	func (m *MilvusStore) normalizeRetrieveOpts(opts RetrieveOptions) (limit int, threshold float32, err error) {
66		if !m.enabled {
67			return 0, 0, fmt.Errorf("milvus store is not enabled")
68		}
69		limit = opts.Limit
70		if limit <= 0 {
71			limit = m.config.DefaultRetrievalLimit
72		}
73		threshold = opts.Threshold
74		if threshold <= 0 {
75			threshold = m.config.DefaultSimilarityThreshold
76		}
77		if opts.Query == "" {
78			return 0, 0, fmt.Errorf("query is required")
79		}
80		if opts.UserID == "" {
81			return 0, 0, fmt.Errorf("user id is required")
82		}
83		return limit, threshold, nil
84	}
85	
86	func retrieveFilterExpr(userID string, types []MemoryType) string {
87		filterExpr := milvusUserScopeFilter(userID)
88		if tf := buildTypeFilter(types); tf != "" {
89			filterExpr = fmt.Sprintf("%s && %s", filterExpr, tf)
90		}
91		return filterExpr
92	}
93	
94	func retrieveSearchTopK(limit int, hybridSearch bool) int {
95		searchTopK := limit * 4
96		if hybridSearch {
97			searchTopK = limit * 8
98		}
99		if searchTopK < 20 {
100			searchTopK = 20
101		}
102		return searchTopK
103	}
104	
105	func (m *MilvusStore) searchMemoryVectors(ctx context.Context, embedding []float32, filterExpr string, searchTopK int) ([]client.SearchResult, error) {
106		logging.Debugf("MilvusStore.Retrieve: filter expression: %s", filterExpr)
107	
108		searchParam, err := entity.NewIndexHNSWSearchParam(64)
109		if err != nil {
110			return nil, fmt.Errorf("failed to create search parameters: %w", err)
111		}
112	
113		var searchResult []client.SearchResult
114		err = m.retryWithBackoff(ctx, func() error {
115			var retryErr error
116			searchResult, retryErr = m.client.Search(
117				ctx,
118				m.collectionName,
119				[]string{},
120				filterExpr,
121				[]string{"id", "content", "memory_type", "metadata"},
122				[]entity.Vector{entity.FloatVector(embedding)},
123				"embedding",
124				entity.COSINE,
125				searchTopK,
126				searchParam,
127			)
128			return retryErr
129		})
130		if err != nil {
131			return nil, fmt.Errorf("milvus search failed after retries: %w", err)
132		}
133		return searchResult, nil
134	}
135	
136	func (m *MilvusStore) finalizeRetrieveResults(sr client.SearchResult, opts RetrieveOptions, limit int, threshold float32) []*RetrieveResult {
137		candidates := m.parseCandidates(sr, opts.UserID)
138		if opts.HybridSearch && len(candidates) > 1 {
139			candidates = m.hybridRerank(candidates, opts)
140		}
141		if opts.AdaptiveThreshold && len(candidates) > 1 {
142			threshold = adaptiveThresholdElbow(candidates, threshold)
143		}
144	
145		results := applyRetrieveThreshold(candidates, limit, threshold)
146		if len(results) > 0 {
147			ids := make([]string, len(results))
148			for i, r := range results {
149				ids[i] = r.Memory.ID
150			}
151			go m.recordRetrievalBatch(ids)
152		}
153		return results
154	}
155	
156	func applyRetrieveThreshold(candidates []*RetrieveResult, limit int, threshold float32) []*RetrieveResult {
157		results := make([]*RetrieveResult, 0, limit)
158		for _, c := range candidates {
159			if c.Score < threshold {
160				continue
161			}
162			results = append(results, c)
163			if len(results) >= limit {
164				break
165			}
166		}
167		return results
168	}
169	
170	func adaptiveThresholdElbow(candidates []*RetrieveResult, floor float32) float32 {
171		if len(candidates) < 2 {
172			return floor
173		}
174	
175		maxGap := float32(0)
176		elbowIdx := 0
177		for i := 1; i < len(candidates); i++ {
178			gap := candidates[i-1].Score - candidates[i].Score
179			if gap > maxGap {
180				maxGap = gap
181				elbowIdx = i
182			}
183		}
184	
185		if maxGap < 0.05 {
186			return floor
187		}
188	
189		adaptive := candidates[elbowIdx-1].Score - maxGap/2
190		if adaptive > floor {
191			return adaptive
192		}
193		return floor
194	}
195	
196	func (m *MilvusStore) parseCandidates(sr client.SearchResult, defaultUserID string) []*RetrieveResult {
197		fieldIdx := indexSearchResultFields(sr.Fields)
198		results := make([]*RetrieveResult, 0, len(sr.Scores))
199		for i, score := range sr.Scores {
200			if candidate := retrieveCandidateFromRow(sr.Fields, fieldIdx, i, score, defaultUserID); candidate != nil {
201				results = append(results, candidate)
202			}
203		}
204		return results
205	}
206	
207	type searchFieldIndex struct {
208		id, content, memoryType, metadata int
209	}
210	
211	func indexSearchResultFields(fields []entity.Column) searchFieldIndex {
212		idx := searchFieldIndex{id: -1, content: -1, memoryType: -1, metadata: -1}
213		for i, field := range fields {
214			switch field.Name() {
215			case "id":
216				idx.id = i
217			case "content":
218				idx.content = i
219			case "memory_type":
220				idx.memoryType = i
221			case "metadata":
222				idx.metadata = i
223			}
224		}
225		return idx
226	}
227	
228	func retrieveCandidateFromRow(fields []entity.Column, idx searchFieldIndex, row int, score float32, defaultUserID string) *RetrieveResult {
229		id := varcharFieldValue(fields, idx.id, row)
230		content := varcharFieldValue(fields, idx.content, row)
231		memType := varcharFieldValue(fields, idx.memoryType, row)
232		if id == "" || content == "" {
233			return nil
234		}
235	
236		metadata := parseRetrieveMetadata(fields, idx.metadata, row)
237		mem := &Memory{ID: id, Content: content, Type: MemoryType(memType)}
238		populateMemoryFromRetrieveMetadata(mem, metadata, defaultUserID)
239		return &RetrieveResult{Memory: mem, Score: score}
240	}
241	
242	func varcharFieldValue(fields []entity.Column, fieldIdx, row int) string {
243		if fieldIdx < 0 || fieldIdx >= len(fields) {
244			return ""
245		}
246		col, ok := fields[fieldIdx].(*entity.ColumnVarChar)
247		if !ok || col.Len() <= row {
248			return ""
249		}
250		val, err := col.ValueByIdx(row)
251		if err != nil {
252			return ""
253		}
254		return val
255	}
256	
257	func parseRetrieveMetadata(fields []entity.Column, fieldIdx, row int) map[string]interface{} {
258		metadata := make(map[string]interface{})
259		if fieldIdx < 0 || fieldIdx >= len(fields) {
260			return metadata
261		}
262		col, ok := fields[fieldIdx].(*entity.ColumnVarChar)
263		if !ok || col.Len() <= row {
264			return metadata
265		}
266		metadataVal, err := col.ValueByIdx(row)
267		if err != nil || metadataVal == "" {
268			return metadata
269		}
270		if err := json.Unmarshal([]byte(metadataVal), &metadata); err != nil {
271			metadata["raw"] = metadataVal
272		} else {
273			metadata["_raw_source"] = metadataVal
274		}
275		return metadata
276	}
277	
278	func populateMemoryFromRetrieveMetadata(mem *Memory, metadata map[string]interface{}, defaultUserID string) {
279		if userID, ok := metadata["user_id"].(string); ok {
280			mem.UserID = userID
281		} else if defaultUserID != "" {
282			mem.UserID = defaultUserID
283		}
284		if projectID, ok := metadata["project_id"].(string); ok {
285			mem.ProjectID = projectID
286		}
287		if source, ok := metadata["source"].(string); ok {
288			mem.Source = source
289		}
290		if importance, ok := metadata["importance"].(float64); ok {
291			mem.Importance = float32(importance)
292		} else if importance, ok := metadata["importance"].(float32); ok {
293			mem.Importance = importance
294		}
295		if accessCount, ok := metadata["access_count"].(float64); ok {
296			mem.AccessCount = int(accessCount)
297		}
298		if lastAccessed, ok := metadata["last_accessed"].(float64); ok {
299			mem.LastAccessed = time.Unix(int64(lastAccessed), 0)
300		}
301	}
302	
303	func (m *MilvusStore) hybridRerank(candidates []*RetrieveResult, opts RetrieveOptions) []*RetrieveResult {
304		pseudoChunks := make(map[string]vectorstore.EmbeddedChunk, len(candidates))
305		vectorScores := make(map[string]float64, len(candidates))
