1	package memory
2	
3	import (
4		"math"
5		"regexp"
6		"sort"
7		"strings"
8		"time"
9	
10		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/config"
11		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/observability/logging"
12	)
13	
14	// defaultBlockPatterns is empty by default.
15	// Operators can add custom block_patterns via MemoryReflectionConfig.
16	var defaultBlockPatterns = []string{}
17	
18	// ReflectionGate filters retrieved memories before injection using heuristic
19	// rules: recency decay, redundancy dedup, and token budget enforcement.
20	// No LLM calls -- sub-millisecond overhead.
21	//
22	// Adversarial content blocking is handled upstream: SR's jailbreak classifier
23	// gates the write path (only clean requests produce memories), and sanitize.go
24	// provides a regex fallback. Custom block patterns can still be added via config.
25	//
26	// Inspired by RMM (ACL 2025) retrospective reflection, adapted for
27	// infrastructure-layer operation where latency must be minimal.
28	type ReflectionGate struct {
29		maxTokens      int
30		decayHalfLife  float64 // days
31		dedupThreshold float32
32		blockPatterns  []*regexp.Regexp
33	}
34	
35	// newHeuristicFilter is the MemoryFilterFactory registered as "heuristic".
36	func newHeuristicFilter(global config.MemoryReflectionConfig, perDecision *config.MemoryReflectionConfig) MemoryFilter {
37		return NewReflectionGate(global, perDecision)
38	}
39	
40	// NewReflectionGate creates a gate from the global config, optionally
41	// overridden by a per-decision plugin config.
42	// Prefer NewMemoryFilter() in production code -- it selects the algorithm
43	// from config and delegates to the appropriate factory.
44	func NewReflectionGate(global config.MemoryReflectionConfig, perDecision *config.MemoryReflectionConfig) *ReflectionGate {
45		cfg := resolveReflectionConfig(global, perDecision)
46	
47		if !cfg.ReflectionEnabled() {
48			return nil
49		}
50	
51		maxTokens := cfg.MaxInjectTokens
52		if maxTokens <= 0 {
53			maxTokens = 2048
54		}
55	
56		decayDays := cfg.RecencyDecayDays
57		if decayDays <= 0 {
58			decayDays = 30
59		}
60	
61		dedupThresh := cfg.DedupThreshold
62		if dedupThresh <= 0 {
63			dedupThresh = 0.90
64		}
65	
66		patterns := buildBlockPatterns(cfg.BlockPatterns)
67	
68		return &ReflectionGate{
69			maxTokens:      maxTokens,
70			decayHalfLife:  float64(decayDays),
71			dedupThreshold: dedupThresh,
72			blockPatterns:  patterns,
73		}
74	}
75	
76	// Filter applies all heuristic checks and returns the memories that pass.
77	// The returned slice is a subset of the input, re-scored and trimmed to
78	// the token budget.
79	func (g *ReflectionGate) Filter(memories []*RetrieveResult) []*RetrieveResult {
80		if g == nil || len(memories) == 0 {
81			return memories
82		}
83	
84		now := time.Now()
85		original := len(memories)
86	
87		// Step 1: Block adversarial content
88		memories = g.filterBlocked(memories)
89	
90		// Step 2: Apply recency decay to scores
91		g.applyRecencyDecay(memories, now)
92	
93		// Step 3: Re-sort by adjusted score (descending)
94		sort.Slice(memories, func(i, j int) bool {
95			return memories[i].Score > memories[j].Score
96		})
97	
98		// Step 4: Deduplicate near-identical memories
99		memories = g.dedup(memories)
100	
101		// Step 5: Enforce token budget
102		memories = g.enforceTokenBudget(memories)
103	
104		if len(memories) < original {
105			logging.Debugf("ReflectionGate: %d→%d memories (blocked=%d, dedup+budget trimmed)",
106				original, len(memories), original-len(memories))
107		}
108	
109		return memories
110	}
111	
112	// filterBlocked removes memories whose content matches any block pattern.
113	func (g *ReflectionGate) filterBlocked(memories []*RetrieveResult) []*RetrieveResult {
114		kept := make([]*RetrieveResult, 0, len(memories))
115		for _, m := range memories {
116			if m.Memory == nil {
117				continue
118			}
119			blocked := false
120			for _, pat := range g.blockPatterns {
121				if pat.MatchString(m.Memory.Content) {
122					logging.Debugf("ReflectionGate: blocked memory id=%s (pattern=%s)", m.Memory.ID, pat.String())
123					blocked = true
124					break
125				}
126			}
127			if !blocked {
128				kept = append(kept, m)
129			}
130		}
131		return kept
132	}
133	
134	// applyRecencyDecay multiplies each memory's score by an exponential decay
135	// factor based on age: factor = exp(-0.693 * age_days / halfLife).
136	// At halfLife days old the factor is 0.5; at 0 days it's 1.0.
137	func (g *ReflectionGate) applyRecencyDecay(memories []*RetrieveResult, now time.Time) {
138		ln2 := math.Ln2 // 0.693...
139		for _, m := range memories {
140			if m.Memory == nil || m.Memory.CreatedAt.IsZero() {
141				continue
142			}
143			ageDays := now.Sub(m.Memory.CreatedAt).Hours() / 24.0
144			if ageDays < 0 {
145				ageDays = 0
146			}
147			factor := math.Exp(-ln2 * ageDays / g.decayHalfLife)
148			m.Score = float32(float64(m.Score) * factor)
149		}
150	}
151	
152	// dedup removes memories that are near-duplicates of a higher-scored memory.
153	// Uses simple content similarity (Jaccard on word sets) as a proxy for
154	// cosine similarity -- avoids needing embeddings at this stage.
155	func (g *ReflectionGate) dedup(memories []*RetrieveResult) []*RetrieveResult {
156		if len(memories) <= 1 {
157			return memories
158		}
159	
160		kept := make([]*RetrieveResult, 0, len(memories))
161		for i, candidate := range memories {
162			isDup := false
163			for _, existing := range kept {
164				if wordJaccard(candidate.Memory.Content, existing.Memory.Content) >= g.dedupThreshold {
165					logging.Debugf("ReflectionGate: dedup memory id=%s (similar to id=%s)",
166						candidate.Memory.ID, existing.Memory.ID)
167					isDup = true
168					break
169				}
170			}
171			if !isDup {
172				kept = append(kept, memories[i])
173			}
174		}
175		return kept
176	}
177	
178	// enforceTokenBudget keeps memories in score-descending order until the
179	// cumulative estimated token count exceeds the budget.
180	func (g *ReflectionGate) enforceTokenBudget(memories []*RetrieveResult) []*RetrieveResult {
181		var total int
182		for i, m := range memories {
183			tokens := estimateTokens(m.Memory.Content)
184			if total+tokens > g.maxTokens && i > 0 {
185				logging.Debugf("ReflectionGate: token budget %d reached at %d/%d memories", g.maxTokens, i, len(memories))
186				return memories[:i]
187			}
188			total += tokens
189		}
190		return memories
191	}
192	
193	// wordJaccard computes Jaccard similarity on lowercased word sets.
194	func wordJaccard(a, b string) float32 {
195		setA := wordSet(a)
196		setB := wordSet(b)
197	
198		if len(setA) == 0 && len(setB) == 0 {
199			return 1.0
200		}
201	
202		intersection := 0
203		for w := range setA {
204			if setB[w] {
205				intersection++
206			}
207		}
208		union := len(setA) + len(setB) - intersection
209		if union == 0 {
210			return 0
211		}
212		return float32(intersection) / float32(union)
213	}
214	
215	func wordSet(s string) map[string]bool {
216		words := strings.Fields(strings.ToLower(s))
217		set := make(map[string]bool, len(words))
218		for _, w := range words {
219			set[w] = true
220		}
221		return set
222	}
223	
224	// estimateTokens gives a rough token count (words * 1.3, the common
225	// English approximation). Good enough for budget enforcement.
226	func estimateTokens(s string) int {
227		words := len(strings.Fields(s))
228		return int(math.Ceil(float64(words) * 1.3))
229	}
230	
231	// resolveReflectionConfig merges per-decision overrides into global config.
232	func resolveReflectionConfig(global config.MemoryReflectionConfig, perDecision *config.MemoryReflectionConfig) config.MemoryReflectionConfig {
233		if perDecision == nil {
234			return global
235		}
236		merged := global
237		if perDecision.Enabled != nil {
238			merged.Enabled = perDecision.Enabled
239		}
240		if perDecision.Algorithm != "" {
241			merged.Algorithm = perDecision.Algorithm
242		}
243		if perDecision.MaxInjectTokens > 0 {
244			merged.MaxInjectTokens = perDecision.MaxInjectTokens
245		}
246		if perDecision.RecencyDecayDays > 0 {
247			merged.RecencyDecayDays = perDecision.RecencyDecayDays
248		}
249		if perDecision.DedupThreshold > 0 {
250			merged.DedupThreshold = perDecision.DedupThreshold
251		}
252		if len(perDecision.BlockPatterns) > 0 {
253			merged.BlockPatterns = perDecision.BlockPatterns
254		}
255		return merged
256	}
257	
258	func buildBlockPatterns(userPatterns []string) []*regexp.Regexp {
259		all := make([]string, 0, len(defaultBlockPatterns)+len(userPatterns))
260		all = append(all, defaultBlockPatterns...)
261		all = append(all, userPatterns...)
262		compiled := make([]*regexp.Regexp, 0, len(all))
263		for _, p := range all {
264			re, err := regexp.Compile(p)
265			if err != nil {
266				logging.Warnf("ReflectionGate: invalid block pattern %q: %v", p, err)
267				continue
268			}
269			compiled = append(compiled, re)
270		}
271		return compiled
272	}
