12	)
13	
14	// InMemoryStore is an in-memory implementation of Store for testing and POC.
15	// It stores memories in memory with embedding-based similarity search.
16	type InMemoryStore struct {
17		mu              sync.RWMutex
18		memories        map[string]*Memory // ID -> Memory
19		enabled         bool
20		embeddingConfig EmbeddingConfig
21	}
22	
23	// NewInMemoryStore creates a new in-memory memory store with default embedding config.
24	func NewInMemoryStore() *InMemoryStore {
25		return NewInMemoryStoreWithConfig(EmbeddingConfig{Model: EmbeddingModelBERT})
26	}
27	
28	// NewInMemoryStoreWithConfig creates a new in-memory memory store with custom embedding config.
29	func NewInMemoryStoreWithConfig(embeddingConfig EmbeddingConfig) *InMemoryStore {
30		return &InMemoryStore{
31			memories:        make(map[string]*Memory),
32			enabled:         true,
33			embeddingConfig: embeddingConfig,
34		}
35	}
36	
37	// IsEnabled returns whether the store is enabled.
38	func (s *InMemoryStore) IsEnabled() bool {
39		return s.enabled
40	}
41	
42	// Store saves a new memory.
43	func (s *InMemoryStore) Store(ctx context.Context, memory *Memory) error {
44		if !s.enabled {
45			return nil
46		}
47	
48		s.mu.Lock()
49		defer s.mu.Unlock()
50	
51		// Generate embedding if not already set
52		if len(memory.Embedding) == 0 {
53			embedding, err := GenerateEmbedding(memory.Content, s.embeddingConfig)
54			if err != nil {
55				return err
56			}
57			memory.Embedding = embedding
58		}
59	
60		// Check if ID already exists
61		if _, exists := s.memories[memory.ID]; exists {
62			return fmt.Errorf("memory with ID %s already exists", memory.ID)
63		}
64	
65		// Set CreatedAt if not set
66		if memory.CreatedAt.IsZero() {
67			memory.CreatedAt = time.Now()
68		}
69	
70		s.memories[memory.ID] = memory
71		logging.Debugf("InMemoryStore: stored memory id=%s, type=%s, user=%s", memory.ID, memory.Type, memory.UserID)
72		return nil
73	}
74	
75	// Retrieve performs semantic search for relevant memories.
76	func (s *InMemoryStore) Retrieve(ctx context.Context, opts RetrieveOptions) ([]*RetrieveResult, error) {
77		if !s.enabled {
78			return nil, nil
79		}
80	
81		s.mu.RLock()
82		defer s.mu.RUnlock()
83	
84		// Generate embedding for query using unified embedding configuration
85		queryEmbedding, err := GenerateEmbedding(opts.Query, s.embeddingConfig)
86		if err != nil {
87			return nil, err
88		}
89	
90		var results []*RetrieveResult
91	
92		// Search through all memories
93		for _, mem := range s.memories {
94			// Filter by user ID
95			if opts.UserID != "" && mem.UserID != opts.UserID {
96				continue
97			}
98	
99			// Filter by project ID if specified
100			if opts.ProjectID != "" && mem.ProjectID != opts.ProjectID {
101				continue
102			}
103	
104			// Filter by types if specified
105			if len(opts.Types) > 0 {
106				found := false
107				for _, t := range opts.Types {
108					if mem.Type == t {
109						found = true
110						break
111					}
112				}
113				if !found {
114					continue
115				}
116			}
117	
118			// Calculate similarity
119			similarity := cosineSimilarity(queryEmbedding, mem.Embedding)
120			if similarity < opts.Threshold {
121				continue
122			}
123	
124			results = append(results, &RetrieveResult{
125				Memory: mem,
126				Score:  similarity,
127			})
128		}
129	
130		// Sort by similarity (descending)
131		sort.Slice(results, func(i, j int) bool {
132			return results[i].Score > results[j].Score
133		})
134	
135		// Apply limit
136		if opts.Limit > 0 && len(results) > opts.Limit {
137			results = results[:opts.Limit]
138		}
139	
140		return results, nil
141	}
142	
143	// List returns memories matching the filter criteria, sorted by created_at descending.
144	func (s *InMemoryStore) List(ctx context.Context, opts ListOptions) (*ListResult, error) {
145		if !s.enabled {
146			return nil, fmt.Errorf("store not enabled")
147		}
148	
149		if opts.UserID == "" {
150			return nil, fmt.Errorf("user ID is required for listing memories")
151		}
152	
153		s.mu.RLock()
154		defer s.mu.RUnlock()
155	
156		// Collect matching memories
157		var matching []*Memory
158		for _, mem := range s.memories {
159			if mem.UserID != opts.UserID {
160				continue
161			}
162	
163			if len(opts.Types) > 0 {
164				found := false
165				for _, t := range opts.Types {
166					if mem.Type == t {
167						found = true
168						break
169					}
170				}
171				if !found {
172					continue
173				}
174			}
175	
176			matching = append(matching, mem)
177		}
178	
179		// Sort by created_at descending (newest first)
180		sort.Slice(matching, func(i, j int) bool {
181			return matching[i].CreatedAt.After(matching[j].CreatedAt)
182		})
183	
184		total := len(matching)
185	
186		// Apply limit
187		limit := opts.Limit
188		if limit <= 0 {
189			limit = 20
190		}
191		if limit > 100 {
192			limit = 100
193		}
194	
195		if limit < len(matching) {
196			matching = matching[:limit]
197		}
198	
199		return &ListResult{
200			Memories: matching,
201			Total:    total,
202			Limit:    limit,
203		}, nil
204	}
205	
206	// Get retrieves a memory by ID.
207	func (s *InMemoryStore) Get(ctx context.Context, id string) (*Memory, error) {
208		if !s.enabled {
209			return nil, fmt.Errorf("store not enabled")
210		}
211	
212		s.mu.RLock()
213		defer s.mu.RUnlock()
214	
215		mem, exists := s.memories[id]
216		if !exists {
217			return nil, fmt.Errorf("memory not found: %s", id)
218		}
219	
220		return mem, nil
221	}
222	
223	// Update modifies an existing memory.
224	func (s *InMemoryStore) Update(ctx context.Context, id string, memory *Memory) error {
225		if !s.enabled {
226			return fmt.Errorf("store not enabled")
227		}
228	
229		s.mu.Lock()
230		defer s.mu.Unlock()
231	
232		// Check if memory exists
233		existing, exists := s.memories[id]
234		if !exists {
235			return fmt.Errorf("memory not found: %s", id)
236		}
237	
238		// Regenerate embedding before overwriting Content so the comparison is valid.
239		if existing.Content != memory.Content {
240			embedding, err := GenerateEmbedding(memory.Content, s.embeddingConfig)
241			if err != nil {
242				return err
243			}
244			existing.Embedding = embedding
245		}
246	
247		// Update fields.
248		existing.Content = memory.Content
249		existing.Type = memory.Type
250		existing.UpdatedAt = time.Now()
251		if memory.ProjectID != "" {
252			existing.ProjectID = memory.ProjectID
253		}
254		if memory.Source != "" {
255			existing.Source = memory.Source
256		}
257	
258		logging.Debugf("InMemoryStore: updated memory id=%s", id)
259		return nil
260	}
261	
262	// Forget deletes a memory by ID.
263	func (s *InMemoryStore) Forget(ctx context.Context, id string) error {
264		if !s.enabled {
265			return fmt.Errorf("store not enabled")
266		}
267	
268		s.mu.Lock()
269		defer s.mu.Unlock()
270	
271		if _, exists := s.memories[id]; !exists {
272			return fmt.Errorf("memory not found: %s", id)
273		}
274	
275		delete(s.memories, id)
276		logging.Debugf("InMemoryStore: deleted memory id=%s", id)
277		return nil
278	}
279	
280	// ForgetByScope deletes all memories matching the scope.
281	func (s *InMemoryStore) ForgetByScope(ctx context.Context, scope MemoryScope) error {
282		if !s.enabled {
283			return fmt.Errorf("store not enabled")
284		}
285	
286		s.mu.Lock()
287		defer s.mu.Unlock()
288	
289		var toDelete []string
290		for id, mem := range s.memories {
291			// Must match user ID
292			if mem.UserID != scope.UserID {
293				continue
294			}
295	
296			// Optionally match project ID
297			if scope.ProjectID != "" && mem.ProjectID != scope.ProjectID {
298				continue
299			}
300	
301			// Optionally match types
302			if len(scope.Types) > 0 {
303				found := false
304				for _, t := range scope.Types {
305					if mem.Type == t {
306						found = true
307						break
308					}
309				}
310				if !found {
311					continue
312				}
313			}
314	
315			toDelete = append(toDelete, id)
316		}
317	
318		for _, id := range toDelete {
319			delete(s.memories, id)
320		}
321	
322		logging.Debugf("InMemoryStore: deleted %d memories by scope", len(toDelete))
323		return nil
324	}
325	
326	// CheckConnection verifies the store connection is healthy.
327	// For in-memory store, this is always healthy (no external connection).
328	func (s *InMemoryStore) CheckConnection(ctx context.Context) error {
329		if !s.enabled {
330			return fmt.Errorf("store not enabled")
331		}
332		// In-memory store has no external connection to check
333		return nil
334	}
335	
336	// Close releases resources.
337	func (s *InMemoryStore) Close() error {
338		s.mu.Lock()
339		defer s.mu.Unlock()
340	
341		s.memories = nil
342		s.enabled = false
343		return nil
344	}
345	
346	// cosineSimilarity calculates cosine similarity between two vectors
347	func cosineSimilarity(a, b []float32) float32 {
348		if len(a) != len(b) {
349			return 0
350		}
351	
352		var dotProduct float32
353		var normA, normB float32
354	
355		for i := range a {
356			dotProduct += a[i] * b[i]
357			normA += a[i] * a[i]
358			normB += b[i] * b[i]
359		}
360	
361		if normA == 0 || normB == 0 {
362			return 0
363		}
364	
365		return dotProduct / (float32(math.Sqrt(float64(normA))) * float32(math.Sqrt(float64(normB))))
