1	package memory
2	
3	import (
4		"sync"
5	
6		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/config"
7		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/observability/logging"
8	)
9	
10	var (
11		filterMu       sync.RWMutex
12		filterRegistry = map[string]MemoryFilterFactory{}
13	)
14	
15	func init() {
16		RegisterFilter("heuristic", newHeuristicFilter)
17		RegisterFilter("noop", newNoopFilter)
18	}
19	
20	// RegisterFilter adds a named MemoryFilterFactory to the global registry.
21	// Calling with an existing name replaces the previous factory.
22	// Safe for concurrent use (intended for init-time registration).
23	func RegisterFilter(name string, factory MemoryFilterFactory) {
24		filterMu.Lock()
25		defer filterMu.Unlock()
26		filterRegistry[name] = factory
27	}
28	
29	// RegisteredFilters returns the names of all registered filter algorithms.
30	func RegisteredFilters() []string {
31		filterMu.RLock()
32		defer filterMu.RUnlock()
33		names := make([]string, 0, len(filterRegistry))
34		for name := range filterRegistry {
35			names = append(names, name)
36		}
37		return names
38	}
39	
40	// NewMemoryFilter constructs the appropriate MemoryFilter based on configuration.
